/*  SUMO SLAP DOWN — the API, as a Supabase Edge Function
 *  ---------------------------------------------------------------------
 *  Same contract as the old Apps Script web app: GET ?action=... and POST
 *  a JSON body as text/plain (no CORS preflight), JSON back. The pages
 *  only had to change the URL in gg-config.js.
 *
 *  sumo-fantasy.gs runs unchanged inside engine.js. backend.js is that
 *  file as a string, regenerated by `node tools/build-backend.mjs` (the
 *  test runner refuses to go green while it is stale).
 *
 *  A few actions belong to the platform rather than the game. They all
 *  start with "__" so they can never collide with a .gs action:
 *    GET  ?action=__health                         engine + store status
 *    POST {action:"__import", key, step, ...}      the Sheet -> Postgres copy
 *    POST {action:"__export", adminKey, step, ...} Postgres -> the Sheet, and checksums
 *    POST {action:"__cron", key, job}              pg_cron runs triggers here
 *    POST {action:"__maint", adminKey, on, live}   pause writes for a cutover
 *  ------------------------------------------------------------------- */

import { createEngine, MIME } from './engine.js';
import { createRestStore } from './store.js';
import { SOURCE, SOURCE_SHA256 } from './backend.js';
import { SEED_SHEETS } from './seed-sheets.js';

const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? '';
const SECRET = (() => {
  try {
    const keys = JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS') ?? '{}');
    if (keys.default) return String(keys.default);
    const first = Object.values(keys)[0];
    if (first) return String(first);
  } catch (_) { /* fall through to the legacy key */ }
  return Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
})();

// The old Apps Script deployment. Until the first import has brought
// ADMIN_KEY across, it is the only thing that can vouch for an admin key.
// (GG_LEGACY_EXEC lets the local rehearsal point this somewhere harmless.)
const LEGACY_EXEC = Deno.env.get('GG_LEGACY_EXEC') ||
  'https://script.google.com/macros/s/AKfycbyrhng3sZoNNpgDA2JApz2Z0xx01x9N1TwnGhqkMfbmXCR-q11NIqlB_i3krHPZ3yZ7GA/exec';
const SELF_URL = SUPABASE_URL.replace(/\/+$/, '') + '/functions/v1/api';
const BACKEND_VERSION = (SOURCE.match(/var BACKEND_VERSION = '([^']*)'/) || [])[1] || '';

// Triggers the old project ran on a timer, plus the keeper clock (every five
// minutes, so a keeper window closes on draft day itself). pg_cron calls
// __cron with one of these.
const CRON_JOBS = new Set(['refreshResults', 'keeperClock']);

const store = createRestStore({ url: SUPABASE_URL, key: SECRET });
const engine = createEngine({ source: SOURCE, store, selfUrl: SELF_URL, seed: SEED_SHEETS });

const CORS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'content-type',
  'Access-Control-Max-Age': '86400'
};

type Reply = { status?: number; mime?: string; text: string; attempts?: number; runs?: number };
const json = (obj: unknown, status = 200): Reply => ({ status, mime: MIME.JSON, text: JSON.stringify(obj) });

function sameSecret(a: string, b: string): boolean {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

async function props(): Promise<Record<string, string>> {
  const res = await store.load([], true);
  return (res && res.props) || {};
}

/* Is this the real admin key? Once imported, the copy in gg_props answers.
   Before that (and if the key was rotated on the old side since), ask the
   old backend, whose own gate rate-limits wrong guesses. */
async function adminKeyOk(key: string, p: Record<string, string>): Promise<boolean> {
  key = String(key || '').trim();
  if (!key) return false;
  if (p.ADMIN_KEY && sameSecret(key, String(p.ADMIN_KEY).trim())) return true;
  try {
    const r = await fetch(LEGACY_EXEC, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({ action: 'adminBasho', adminKey: key })
    });
    const j = await r.json();
    return !!(j && j.ok);
  } catch (_) {
    return false;
  }
}

async function handleImport(body: any): Promise<Reply> {
  const p = await props();
  if (!(await adminKeyOk(body.key, p))) return json({ ok: false, error: 'Not authorised.' });
  switch (body.step) {
    case 'begin':
      return json(await store.importBegin());
    case 'rows':
      if (!Array.isArray(body.rows)) return json({ ok: false, error: 'rows must be an array' });
      return json(await store.importRows(String(body.sheet || ''), Number(body.start) || 1, body.rows));
    case 'finish':
      return json(await store.importFinish(body.expected || {}, body.props || {}, body.meta || {}));
    default:
      return json({ ok: false, error: 'unknown import step' });
  }
}

/* A sheet's rows as one string, the same way migrate.gs builds it: trailing
   blank cells dropped, dates tagged. Equal checksums mean equal cells. */
function canonical(rows: unknown[]): string {
  return JSON.stringify(rows.map((r) => {
    const c = Array.isArray(r) ? r.slice() : [];
    while (c.length && (c[c.length - 1] === '' || c[c.length - 1] === null)) c.pop();
    return c;
  }));
}
async function sha256(s: string): Promise<string> {
  const d = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(s));
  return Array.from(new Uint8Array(d), (b) => b.toString(16).padStart(2, '0')).join('');
}

/* The way back, and the proof: migrate.gs reads the store out again with
   this (revertToAppsScript), and compares checksums before going live. */
async function handleExport(body: any): Promise<Reply> {
  const p = await props();
  if (!(await adminKeyOk(body.adminKey, p))) return json({ ok: false, error: 'Not authorised.' });
  const st = await store.stats();
  const sheets: Record<string, { rows: number; v: number }> = (st && st.sheets) || {};
  switch (body.step) {
    case 'list': {
      const own: Record<string, string> = {};
      for (const [k, v] of Object.entries(p)) if (k.slice(0, 2) !== '__') own[k] = String(v);
      return json({ ok: true, sheets, props: own });
    }
    case 'rows': {
      const rows = await store.exportRows(String(body.sheet || ''), Number(body.offset) || 0, Number(body.limit) || 2000);
      return json({ ok: true, rows });
    }
    case 'checksums': {
      const out: Record<string, { rows: number; sha: string }> = {};
      for (const name of Object.keys(sheets)) {
        let rows: unknown[] = [];
        for (let off = 0; off < sheets[name].rows; off += 5000) rows = rows.concat(await store.exportRows(name, off, 5000));
        out[name] = { rows: rows.length, sha: await sha256(canonical(rows)) };
      }
      return json({ ok: true, sheets: out });
    }
    default:
      return json({ ok: false, error: 'unknown export step' });
  }
}

async function handleCron(body: any): Promise<Reply> {
  const p = await props();
  if (!sameSecret(String(body.key || ''), String(p.__CRON_KEY || ''))) return json({ ok: false, error: 'Not authorised.' });
  const job = String(body.job || '');
  if (!CRON_JOBS.has(job)) return json({ ok: false, error: 'unknown job' });
  // Until cutover the data here is a rehearsal copy; leave it alone.
  if (p.__LIVE !== '1') return json({ ok: true, skipped: 'not live yet' });
  const res = await engine.execute({ kind: 'fn', fn: job, key: 'FN ' + job });
  return { status: res.status, mime: res.mime, text: res.text };
}

async function handleMaint(body: any): Promise<Reply> {
  const p = await props();
  if (!(await adminKeyOk(body.adminKey, p))) return json({ ok: false, error: 'Not authorised.' });
  const set: Record<string, string> = {};
  const del: string[] = [];
  if (body.on === true) set.__MAINTENANCE = '1';
  if (body.on === false) del.push('__MAINTENANCE');
  if (body.live === true) set.__LIVE = '1';
  if (body.live === false) del.push('__LIVE');
  await store.commit({ check: null, ops: [], props: { set, del }, cache: null });
  const after = await props();
  return json({ ok: true, maintenance: after.__MAINTENANCE === '1', live: after.__LIVE === '1' });
}

async function handleHealth(): Promise<Reply> {
  const p = await props();
  let meta: any = {};
  try { meta = JSON.parse(p.__IMPORT_META || '{}'); } catch (_) { /* never imported */ }
  return json({
    ok: true, engine: 'supabase', backend: BACKEND_VERSION, source: SOURCE_SHA256.slice(0, 12),
    maintenance: p.__MAINTENANCE === '1', live: p.__LIVE === '1',
    importedAt: p.__IMPORTED_AT || '', exportedAt: meta.exportedAt || '', tz: p.__GG_TZ || 'UTC',
    imported: { sheets: meta.sheets || 0, rows: meta.rows || 0, final: !!meta.final,
      triggers: meta.triggers || [], formulas: meta.formulas || {} }
  });
}

async function route(req: Request): Promise<Reply> {
  const url = new URL(req.url);
  const parameter: Record<string, string> = {};
  const parameters: Record<string, string[]> = {};
  for (const [k, v] of url.searchParams) {
    if (!(k in parameter)) parameter[k] = v;
    (parameters[k] ||= []).push(v);
  }
  const queryString = url.search.replace(/^\?/, '');

  if (req.method === 'GET') {
    const action = parameter.action || 'data';
    if (action === '__health') return handleHealth();
    const e = { parameter, parameters, queryString, contextPath: '', contentLength: -1 };
    return engine.execute({ kind: 'get', e, key: 'GET ' + action });
  }
  if (req.method === 'POST') {
    const contents = await req.text();
    let body: any = null;
    try { body = JSON.parse(contents || '{}'); } catch (_) { /* doPost reports bad JSON itself */ }
    const action = body && typeof body.action === 'string' ? body.action : '';
    if (action === '__import') return handleImport(body);
    if (action === '__export') return handleExport(body);
    if (action === '__cron') return handleCron(body);
    if (action === '__maint') return handleMaint(body);
    const e = {
      parameter, parameters, queryString, contextPath: '', contentLength: contents.length,
      postData: { contents, length: contents.length, type: req.headers.get('content-type') || 'text/plain', name: 'postData' }
    };
    return engine.execute({ kind: 'post', e, key: 'POST ' + (action || '?') });
  }
  return json({ ok: false, error: 'method not allowed' }, 405);
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });
  const started = Date.now();
  let res: Reply;
  try {
    res = await route(req);
  } catch (err) {
    console.error('api error', err);
    res = json({ ok: false, error: 'Server error: ' + ((err as Error)?.message || String(err)) }, 500);
  }
  return new Response(res.text, {
    status: res.status || 200,
    headers: {
      ...CORS,
      'Content-Type': res.mime || MIME.JSON,
      'Cache-Control': 'no-store',
      'X-GG-Engine': 'supabase',
      // attempts = commits tried, runs = replays; both 1 is the fast path
      'X-GG-Runs': (res.attempts || 0) + '/' + (res.runs || 0),
      'Server-Timing': 'app;dur=' + (Date.now() - started),
      'Access-Control-Expose-Headers': 'X-GG-Engine, X-GG-Runs, Server-Timing'
    }
  });
});
